// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/billing/plans/{policyId}", wrapper.GetPlan)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/billing/plans/{policyId}/installments", wrapper.AdjustSchedule)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/billing/plans/{policyId}/payments", wrapper.ListPayments)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/billing/plans/{policyId}/payments", wrapper.RegisterPayment)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/billing/plans/{policyId}/payments/{paymentId}/reverse", wrapper.ReversePayment)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/billing/plans/{policyId}/collection-activities", wrapper.ListCollectionActivities)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/billing/plans/{policyId}/collection-activities", wrapper.AddCollectionActivity)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/billing/receivables", wrapper.ListReceivables)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/billing/receivables/summary", wrapper.GetReceivablesSummary)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/billing/settings/arrears", wrapper.ListArrearsSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/billing/settings/arrears", wrapper.SetArrearsSetting)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/billing/settings/payments", wrapper.GetPaymentSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/billing/settings/payments", wrapper.SetPaymentSettings)
	})

	return r
}

